import{_ as t,o as r,c as o,a2 as n}from"./chunks/framework.Cz0TtJv6.js";const u=JSON.parse('{"title":"Fees","description":"The DLMM Bot usage fee — 1% GNME buy-and-burn on live winning closes only.","frontmatter":{"title":"Fees","description":"The DLMM Bot usage fee — 1% GNME buy-and-burn on live winning closes only."},"headers":[],"relativePath":"fees.md","filePath":"fees.md","lastUpdated":1786721791000}'),s={name:"fees.md"};function a(i,e,d,l,h,g){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="fees" tabindex="-1">Fees <a class="header-anchor" href="#fees" aria-label="Permalink to &quot;Fees&quot;">​</a></h1><h2 id="usage-fee-gnme-buy-and-burn" tabindex="-1">Usage fee (GNME buy-and-burn) <a class="header-anchor" href="#usage-fee-gnme-buy-and-burn" aria-label="Permalink to &quot;Usage fee (GNME buy-and-burn)&quot;">​</a></h2><p>On each <strong>live winning close</strong>, <strong>1% of measured net profit</strong> buys and burns <a href="https://solscan.io/token/BaDjVCpABEVCdt4LT7ivuzA4izBwJCqnDjrLa8XBtT38" target="_blank" rel="noreferrer">GNME</a> via Jupiter in the same transaction flow as the exit.</p><p><strong>Measured net profit</strong> = wallet open cost → close return + fees earned + rent recovered (the same expression the ledger uses for realized PnL).</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Charged when</strong></td><td>Live mode, winning close only</td></tr><tr><td><strong>Not charged</strong></td><td>Losses, break-even closes, mark-only events, paper mode</td></tr><tr><td><strong>Paper mode</strong></td><td>Logs the fee amount; no swap is sent</td></tr><tr><td><strong>Configurable?</strong></td><td>No — hardcoded in <code>src/executor/profitBurn.ts</code>, not a Settings knob</td></tr><tr><td><strong>Profiles</strong></td><td>Cannot change the fee</td></tr><tr><td><strong>Failed burn</strong></td><td>Amount is held in a pot and retried — not dropped or double-charged</td></tr></tbody></table><p>This is a required product fee, not an operator toggle. Plan for it when sizing live bankroll expectations.</p><h2 id="what-this-is-not" tabindex="-1">What this is not <a class="header-anchor" href="#what-this-is-not" aria-label="Permalink to &quot;What this is not&quot;">​</a></h2><ul><li><strong>Not</strong> Meteora pool fees — those are swap fees earned by your LP position and are separate.</li><li><strong>Not</strong> RPC, Jupiter, or host costs — those are your infrastructure bills.</li><li><strong>Not</strong> charged on every trade or every close — only net <strong>wins</strong> in live mode.</li></ul><p class="cta-row"><a class="doc-btn ghost" href="./risk">Risk &amp; sizing</a><a class="doc-btn ghost" href="./configuration">Configuration</a><a class="doc-btn ghost" href="./faq">FAQ</a></p>',9)])])}const f=t(s,[["render",a]]);export{u as __pageData,f as default};
